#include <stdio.h>

int main(void) {
    int N;
    double D;
    scanf("%d %lf", &N, &D);

    double P[1005], C[1005], dp[1005];

    for (int i = 0; i < N; i++) {
        scanf("%lf %lf", &P[i], &C[i]);
    }

    P[N] = D;

    for (int i = 0; i <= N; i++) {
        dp[i] = 1e100;
    }

    dp[0] = 0.0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j <= N; j++) {
            double dist = P[j] - P[i];
            double cost = (dist * dist) / C[i];
            double val = dp[i] + cost;
            if (val < dp[j]) {
                dp[j] = val;
            }
        }
    }

    printf("%.3f\n", dp[N]);

    return 0;
}
